import{_ as a,c as o,o as r,ai as s}from"./chunks/framework.DMRKKuRm.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"Servidor/faq.md","filePath":"Servidor/faq.md"}'),t={name:"Servidor/faq.md"};function i(l,e,n,c,d,u){return r(),o("div",null,e[0]||(e[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>¿Tienes más preguntas? Iremos actualizando las preguntas más frecuentes.</p><h2 id="¿como-cambio-mi-contrasena-en-el-servidor" tabindex="-1">¿Cómo cambio mi contraseña en el servidor? <a class="header-anchor" href="#¿como-cambio-mi-contrasena-en-el-servidor" aria-label="Permalink to &quot;¿Cómo cambio mi contraseña en el servidor?&quot;">​</a></h2><p>Es muy sencillo, usa el comando <strong><code>/changepassword (antigua contraseña) (nueva contraseña)</code></strong></p><h3 id="pasos-a-seguir" tabindex="-1">Pasos a seguir: <a class="header-anchor" href="#pasos-a-seguir" aria-label="Permalink to &quot;Pasos a seguir:&quot;">​</a></h3><ol><li>Coloca tu contraseña antigua (por ejemplo: <code>Pepito123</code>)</li><li>Coloca tu contraseña nueva, que sea más segura (por ejemplo: <code>Pepito7682</code>)</li></ol><h3 id="ejemplo-de-uso" tabindex="-1">Ejemplo de uso: <a class="header-anchor" href="#ejemplo-de-uso" aria-label="Permalink to &quot;Ejemplo de uso:&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/changepassword</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Pepito123</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Pepito7682</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><em>¡Recuerda! Estos son solo ejemplos. Usa contraseñas seguras y únicas para tu cuenta.</em></p></div><h2 id="¿como-activar-el-modo-premium" tabindex="-1">¿Cómo activar el modo premium? <a class="header-anchor" href="#¿como-activar-el-modo-premium" aria-label="Permalink to &quot;¿Cómo activar el modo premium?&quot;">​</a></h2><p>Para activar el modo premium deberás usar dentro de los lobbies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/premium</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [contraseña]</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">ADVERTENCIA</p><p>Solo para jugadores premium. Si usas el comando siendo no premium perderás el acceso al servidor.</p></div><h2 id="¿como-se-vota-en-el-servidor" tabindex="-1">¿Cómo se vota en el servidor? <a class="header-anchor" href="#¿como-se-vota-en-el-servidor" aria-label="Permalink to &quot;¿Cómo se vota en el servidor?&quot;">​</a></h2><h3 id="para-jugadores-java" tabindex="-1">Para jugadores Java: <a class="header-anchor" href="#para-jugadores-java" aria-label="Permalink to &quot;Para jugadores Java:&quot;">​</a></h3><ol><li>Entra a <strong>Survival</strong> y usa el comando <strong><code>/vote40</code></strong></li><li>Obtendrás un link, ábrelo y te llevará a la página para votar</li><li>Sigue estos pasos: <ul><li><strong>Paso 2:</strong> Pon tu nick</li><li><strong>Paso 3:</strong> Espera la verificación</li><li><strong>Paso 4:</strong> Finaliza el proceso</li></ul></li><li>Haz clic en <strong>&quot;Votar&quot;</strong> y espera un minuto o dos</li><li>Usa <strong><code>/vote40</code></strong> nuevamente en el servidor y recibirás la recompensa</li></ol><h3 id="para-jugadores-bedrock" tabindex="-1">Para jugadores Bedrock: <a class="header-anchor" href="#para-jugadores-bedrock" aria-label="Permalink to &quot;Para jugadores Bedrock:&quot;">​</a></h3><p>Si no puedes hacer clic en enlaces en el chat, deberás ir a nuestro <a href="https://discord.silkcraft.net" target="_blank" rel="noreferrer">Discord</a> y usar el comando <strong><code>!votar</code></strong> en cualquier canal.</p><h2 id="¿como-se-entra-en-bedrock-al-servidor" tabindex="-1">¿Cómo se entra en Bedrock al servidor? <a class="header-anchor" href="#¿como-se-entra-en-bedrock-al-servidor" aria-label="Permalink to &quot;¿Cómo se entra en Bedrock al servidor?&quot;">​</a></h2><p>Sigue estos pasos para conectarte desde Bedrock Edition:</p><ol><li><strong>Añadir nuevo servidor</strong></li><li><strong>Nombre del servidor:</strong> Cualquier nombre (ejemplo: &quot;SilkCraft&quot;)</li><li><strong>IP del servidor:</strong> <code>mc.silkcraft.net</code></li><li><strong>Puerto:</strong> <code>19132</code> (déjalo como está)</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>El puerto <strong>19132</strong> es el puerto predeterminado para Bedrock Edition.</p></div><h2 id="¿como-se-abre-ticket-en-discord" tabindex="-1">¿Cómo se abre ticket en Discord? <a class="header-anchor" href="#¿como-se-abre-ticket-en-discord" aria-label="Permalink to &quot;¿Cómo se abre ticket en Discord?&quot;">​</a></h2><p>Para abrir un ticket en Discord:</p><ol><li>Ve al canal <strong><code>#tickets</code></strong> en nuestro <a href="https://discord.silkcraft.net" target="_blank" rel="noreferrer">Discord</a></li><li>Selecciona la categoría que requieras</li><li>Responde las preguntas que te hace el bot</li><li>Un miembro del staff te responderá el ticket</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Mantén los MDs (mensajes directos) abiertos en Discord para que el staff pueda contactarte.</p></div><h2 id="¿por-que-no-me-llego-nada-de-lo-que-compre-en-la-tienda" tabindex="-1">¿Por qué no me llegó nada de lo que compré en la tienda? <a class="header-anchor" href="#¿por-que-no-me-llego-nada-de-lo-que-compre-en-la-tienda" aria-label="Permalink to &quot;¿Por qué no me llegó nada de lo que compré en la tienda?&quot;">​</a></h2><p>Esto puede ocurrir por dos razones principales:</p><ol><li><strong>Pusiste mal el nick</strong> - Verifica que hayas escrito correctamente tu nombre de usuario</li><li><strong>Eres de Bedrock y no pusiste el punto</strong> - Si eres jugador de Bedrock, debes poner el <strong><code>.</code></strong> (punto) al principio de tu nombre</li></ol><h3 id="¿y-ahora-que-hago" tabindex="-1">¿Y ahora qué hago? <a class="header-anchor" href="#¿y-ahora-que-hago" aria-label="Permalink to &quot;¿Y ahora qué hago?&quot;">​</a></h3><p>Deberás contactar con soporte en <a href="https://discord.silkcraft.net" target="_blank" rel="noreferrer">Discord</a> mediante el sistema de tickets para que te lo arreglen. Para las próximas compras ya sabrás qué hacer.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Recuerda: Si eres de Bedrock, siempre incluye el punto (<code>.</code>) al inicio de tu nombre de usuario al hacer compras.</p></div><h2 id="¿falta-alguna-pregunta" tabindex="-1">¿Falta alguna pregunta? <a class="header-anchor" href="#¿falta-alguna-pregunta" aria-label="Permalink to &quot;¿Falta alguna pregunta?&quot;">​</a></h2><p>Si crees que falta alguna pregunta en nuestro FAQ de la Wiki, puedes hacer una sugerencia en nuestro <a href="https://discord.silkcraft.net" target="_blank" rel="noreferrer">Discord</a>.</p>',34)]))}const h=a(t,[["render",i]]);export{m as __pageData,h as default};
